contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");
        require(depositAmount > 0, "deposit must be positive");
        require(collectAmount <= depositAmount, "collect must not exceed deposit");

        c.SetMinSum(collectAmount); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        uint balBeforeDeposit = address(this).balance;
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint depositedBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;

        uint cBalBeforeCollect = address(c).balance;
        uint testBalBeforeCollect = address(this).balance;

        bool collectReverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            collectReverted = true;
        } else {
            collectReverted = false;
        }

        uint balAfterCollect = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalAfterCollect = address(c).balance;
        uint testBalAfterCollect = address(this).balance;

        assert(collectReverted || (
            balAfterCollect == depositedBalance - collectAmount &&
            cBalAfterCollect == cBalBeforeCollect - collectAmount &&
            testBalAfterCollect == testBalBeforeCollect + collectAmount
        ));
    }

    receive() external payable {}
}

