pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 depositAmount, uint256 collectAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        vm.assume(depositAmount > 0);
        vm.assume(collectAmount <= depositAmount);
        try c.SetMinSum(collectAmount) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint balBeforeDeposit = address(this).balance;
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 depositedBalance;
        try c.balances(address(this)) returns (uint256 __r) { depositedBalance = __r; } catch { return; }
        uint cBalBeforeCollect = address(c).balance;
        uint testBalBeforeCollect = address(this).balance;
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }
        uint256 balAfterCollect;
        try c.balances(address(this)) returns (uint256 __r) { balAfterCollect = __r; } catch { return; }
        uint cBalAfterCollect = address(c).balance;
        uint testBalAfterCollect = address(this).balance;
        assertTrue(collectReverted || (
            balAfterCollect == depositedBalance - collectAmount &&
            cBalAfterCollect == cBalBeforeCollect - collectAmount &&
            testBalAfterCollect == testBalBeforeCollect + collectAmount
        ));
    }

    function testFuzz_run(uint256 depositAmount, uint256 collectAmount) public {
        _run(depositAmount, collectAmount);
    }

